cmd:
printf '[Service]
# Порожній Environment= СКИДАЄ увесь попередній перелік,
# інакше systemd лише додає і CABINET_NO_PASSWORD лишається.
Environment=
Environment=CABINET_PORT=8793
' > /etc/systemd/system/unitex-cabinet.service.d/override.conf ; systemctl daemon-reload && systemctl restart unitex-cabinet && sleep 3 ; systemctl show unitex-cabinet -p Environment ; systemctl is-active unitex-cabinet ; echo '=== живий тест: вхід лише з поштою, без пароля ===' ; curl -s -o /tmp/r.html -w 'код=%{http_code}
' -X POST -d 'email=irynakarmazina@gmail.com' -H 'Origin: https://cabinet.unitex.od.ua' -c /tmp/k2 https://cabinet.unitex.od.ua/login ; grep -o 'Невірна пошта або пароль\|Вкажіть пароль\|пароль' /tmp/r.html | head -2 ; curl -s -b /tmp/k2 -o /tmp/p2.html -w 'сторінка після спроби=%{http_code}
' https://cabinet.unitex.od.ua/ ; echo -n 'чи видно угоди ГРАНД МАРИН: ' ; grep -c 'ГРАНД МАРИН' /tmp/p2.html ; echo '=== старі файли з веба ===' ; curl -s -o /dev/null -w 'cabinet.html: %{http_code}
' https://unitex-os.od.ua/cabinet.html 2>/dev/null || true ; ls /root/unitex-os-www/ | grep -i cabinet || echo 'у веб-каталозі файлів cabinet* немає' ; rm -f /tmp/k2 /tmp/p2.html /tmp/r.html
